import sys
from math import sqrt

def count_numbers_with_9_divisors(N):
    # A number has exactly 9 divisors if and only if it is of the form p^8 or p^2 * q^2
    # where p and q are distinct prime numbers.

    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    count = 0
    limit = int(sqrt(N))

    # Check for numbers of the form p^8
    for p in range(2, limit + 1):
        if is_prime(p):
            if p**8 > N:
                break
            count += 1

    # Check for numbers of the form p^2 * q^2
    primes = [p for p in range(2, limit + 1) if is_prime(p)]
    for i in range(len(primes)):
        for j in range(i + 1, len(primes)):
            p, q = primes[i], primes[j]
            if p**2 * q**2 > N:
                break
            count += 1

    return count

# Read input from standard input
N = int(sys.stdin.read().strip())

# Solve the problem
result = count_numbers_with_9_divisors(N)

# Write the result to standard output
print(result)
