            root = i
            break

    return root

def get_children(root, edges, N):
    children = defaultdict(list)
    for u, v in edges:
        if u == root:
            children[root].append(v)
        elif v == root:
            children[root].append(u)

    return children

def count_leaves(node, children):
    if node not in children:
        return 1
    return sum(count_leaves(child, children) for child in children[node])

def is_snowflake_tree(children, x, y):
