def count_connected_components(n, edges):
    visited = [False] * n
    def dfs(node):
        stack = [node]
        while stack:
            current = stack.pop()
            if not visited[current]:
                visited[current] = True
                for neighbor in edges[current]:
                    stack.append(neighbor)

