import sys
from collections import defaultdict

MOD = 998244353

def factorial(n):
    if n == 0:
        return 1
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % MOD
    return result

def inverse_mod(a, p):
    return pow(a, p - 2, p)

def binomial_coefficient(n, k, p):
    num = factorial(n)
    den = (factorial(k) * factorial(n - k)) % p
    return (num * inverse_mod(den, p)) % p

def solve():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    A = list(map(int, data[1:N+1]))
    B = list(map(int, data[N+1:2*N+1]))

    # Count occurrences of each number in A and B
    count_A = defaultdict(int)
    count_B = defaultdict(int)
    for x in A:
        count_A[x] += 1
    for x in B:
        if x != -1:
            count_B[x] += 1

    # Check if counts are valid
    for i in range(1, 2*N + 1):
        if count_A[i] > 1 or count_B[i] > 1:
            print(0)
            return

    # Calculate the number of valid pairs (a, b)
    result = 1
    for i in range(1, 2*N + 1):
        if count_A[i] == 1 and count_B[i] == 1:
            result = (result * binomial_coefficient(N, 1, MOD)) % MOD
        elif count_A[i] == 1 and count_B[i] == 0:
            result = (result * binomial_coefficient(N, 1, MOD)) % MOD
        elif count_A[i] == 0 and count_B[i] == 1:
            result = (result * binomial_coefficient(N, 1, MOD)) % MOD

    print(result)

