from collections import Counter

class Solution:
    def countBalancedPermutations(self, num: str) -> int:
        MOD = 10**9 + 7

        # Count the occurrences of each digit
        count = Counter(num)

        # Calculate the factorial of a number
        def factorial(n):
            if n == 0 or n == 1:
                return 1
            result = 1
            for i in range(2, n + 1):
                result = (result * i) % MOD
            return result

        # Calculate the number of ways to choose k items from n items
        def combinations(n, k):
            return factorial(n) // (factorial(k) * factorial(n - k))

        # Calculate the number of balanced permutations
        total_permutations = factorial(len(num))
        left_sum = 0
        right_sum = sum(count[digit] for digit in count)
        balanced_count = 0

        for digit in count:
            right_sum -= count[digit]
            for i in range(left_sum + 1, right_sum + 1):
                balanced_count += combinations(left_sum + right_sum, i) * combinations(right_sum, i - left_sum)
            left_sum += count[digit]

        return (total_permutations * pow(balanced_count, MOD - 2, MOD)) % MOD
