class Solution:
    def countValidSelections(self, nums: List[int]) -> int:
        n = len(nums)
        result = 0

        for start in range(n):
            if nums[start] != 0:
                continue

            left, right = start, start
            direction = 1  # 1 for right, -1 for left
            while True:
                if direction == 1:
                    right += 1
                else:
                    left -= 1

                if right >= n or left < 0:
                    break

                if nums[right] == 0:
                    if direction == 1:
                        right += 1
                    else:
                        left -= 1

                    if right >= n or left < 0:
                        break

                    direction *= -1
                    if direction == 1:
                        right += 1
                    else:
                        left -= 1

                if nums[left] == 0:
                    if direction == 1:
                        left += 1
                    else:
                        left -= 1

                    if right >= n or left < 0:
                        break

                    direction *= -1
                    if direction == 1:
                        left += 1
                    else:
                        left -= 1

                nums[right] -= 1
                nums[left] -= 1

            if all(x == 0 for x in nums):
                result += 1

        return result
