class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        from heapq import heappop, heappush

        # Build the graph
        graph = defaultdict(list)
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        # Function to calculate the maximum sum of weights
        def dfs(node, parent):
            max_weights = []
            total_weight = 0
            for neighbor, weight in graph[node]:
                if neighbor != parent:
                    child_weight = dfs(neighbor, node)
                    heappush(max_weights, -child_weight)
                    total_weight += child_weight

            # If there are more than k children, remove the smallest ones
            while len(max_weights) > k:
                total_weight -= -heappop(max_weights)

            return total_weight + sum(-w for w in max_weights)

        # Start DFS from node 0
        return dfs(0, -1)
