        for i in range(n):
            if nums[i] > 0:
                steps = nums[i]
                result[i] = (i + steps) % n
            elif nums[i] < 0:
                steps = abs(nums[i])
                result[i] = (i - steps) % n
            else:
                result[i] = nums[i]

        return result
