        max_val = max(nums)
        if max_val < k:
            return -1

        operations = 0
        while max_val > k:
            valid_h = None
            for num in nums:
                if num > k:
                    if valid_h is None or num == valid_h:
                        valid_h = num
                    else:
                        break
            else:
                operations += sum(1 for num in nums if num > k)
                max_val = k
                continue

            for i in range(len(nums)):
                if nums[i] > k and nums[i] == valid_h:
                    nums[i] = k
                    operations += 1
            max_val = valid_h

        return operations
