class Solution:
    def findMinimumTime(self, strength: List[int], K: int) -> int:
        n = len(strength)

        @lru_cache(None)
        def dp(i, x):
            if i >= n:
                return 0

            # Option 1: Skip the current lock
            time_skip = dp(i + 1, x) + max(0, strength[i] - (x * (i + 1)))

            # Option 2: Break the current lock
            time_break = float('inf')
            energy = 0
            j = i
            while j < n and energy < strength[j]:
                energy += x * (j - i + 1)
                time_break = min(time_break, dp(j + 1, x + K) + max(0, strength[j] - energy))
                j += 1

            return min(time_skip, time_break)

        return dp(0, 1)
