class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        parent = list(range(len(nums)))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                parent[rootX] = rootY

        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if (nums[i] * nums[j]) // math.gcd(nums[i], nums[j]) <= threshold:
                    union(i, j)

        return sum(1 for i in range(len(nums)) if i == parent[i])
