        # Create adjacency lists for both sets of currency pairs
        graph1 = {}
        for i in range(len(pairs1)):
            start, target = pairs1[i]
            if start not in graph1:
                graph1[start] = []
            if target not in graph1:
                graph1[target] = []
            graph1[start].append((target, rates1[i]))
            graph1[target].append((start, 1 / rates1[i]))

        graph2 = {}
        for i in range(len(pairs2)):
            start, target = pairs2[i]
            if start not in graph2:
                graph2[start] = []
            if target not in graph2:
                graph2[target] = []
            graph2[start].append((target, rates2[i]))
            graph2[target].append((start, 1 / rates2[i]))

        # Function to find the maximum amount using Dijkstra's algorithm
        def dijkstra(graph, start):
            distances = {currency: float('-inf') for currency in graph}
            distances[start] = 1.0
            pq = [(1.0, start)]

            while pq:
                current_dist, current_currency = heapq.heappop(pq)

                if current_dist < distances[current_currency]:
                    continue

                for neighbor, weight in graph[current_currency]:
                    distance = current_dist * weight

                    if distance > distances[neighbor]:
                        distances[neighbor] = distance
                        heapq.heappush(pq, (distance, neighbor))

            return distances

        # Find the maximum amount for each day
        max_amount_day1 = dijkstra(graph1, initialCurrency)
        max_amount_day2 = dijkstra(graph2, initialCurrency)

        # Combine the results from both days
        result = 0.0
        for currency, dist1 in max_amount_day1.items():
            if currency in max_amount_day2:
                result = max(result, dist1 * max_amount_day2[currency])

        return result
