class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        from collections import Counter

        n = len(s)
        min_length = float('inf')

        for i in range(n):
            flips = 0
            count = Counter()
            max_len = 0

            for j in range(i, n):
                if s[j] != s[i]:
                    flips += 1
                count[s[j]] += 1

                while flips > numOps:
                    if s[count['0'] + count['1']] != s[i]:
                        flips -= 1
                    count[s[count['0'] + count['1']]] -= 1
                    if count[s[count['0'] + count['1']]] == 0:
                        del count[s[count['0'] + count['1']]]

                max_len = max(max_len, j - i + 1)

            min_length = min(min_length, n - max_len)

        return min_length
