class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        if k == 0:
            return pow(m, n, MOD)

        dp = [[0] * (k + 1) for _ in range(n)]
        for j in range(1, m + 1):
            dp[0][0] += 1

        for i in range(1, n):
            prefix_sum = [0] * (k + 1)
            for j in range(1, m + 1):
                dp[i][0] = (dp[i][0] + dp[i-1][0]) % MOD
                for l in range(1, min(i+1, k+1)):
                    dp[i][l] = (dp[i][l] + dp[i-1][l-1] + prefix_sum[l-1]) % MOD
                prefix_sum[l] = (prefix_sum[l] + dp[i][l]) % MOD

        return dp[n-1][k]
