class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        MOD = 10**9 + 7
        m, n = len(grid), len(grid[0])

        # Initialize DP table
        dp = [[[0] * 16 for _ in range(n)] for _ in range(m)]

        # Starting point
        dp[0][0][grid[0][0]] = 1

        # Fill the first row
        for j in range(1, n):
            for xor_val in range(16):
                if dp[0][j-1][xor_val]:
                    dp[0][j][(xor_val ^ grid[0][j])] += dp[0][j-1][xor_val]

        # Fill the first column
        for i in range(1, m):
            for xor_val in range(16):
                if dp[i-1][0][xor_val]:
                    dp[i][0][(xor_val ^ grid[i][0])] += dp[i-1][0][xor_val]

        # Fill the rest of the DP table
        for i in range(1, m):
            for j in range(1, n):
                for xor_val in range(16):
                    if dp[i-1][j][xor_val]:
                        dp[i][j][(xor_val ^ grid[i][j])] += dp[i-1][j][xor_val]
                    if dp[i][j-1][xor_val]:
                        dp[i][j][(xor_val ^ grid[i][j])] += dp[i][j-1][xor_val]

        # The answer is the number of ways to reach the bottom-right corner with XOR value k
        return dp[m-1][n-1][k] % MOD
