def matrix_power(matrix: List[List[int]], power: int, p: int) -> List[List[int]]:
    result = [[int(i == j) for j in range(len(matrix))] for i in range(len(matrix))]
    while power > 0:
        if power % 2 == 1:
            result = matrix_multiply(result, matrix, p)
        matrix = matrix_multiply(matrix, matrix, p)
        power //= 2
    return result

def matrix_multiply(A: List[List[int]], B: List[List[int]], p: int) -> List[List[int]]:
    N = len(A)
    C = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            for k in range(N):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % p
    return C

def main():
