    total_sum = pow(p - 1, num_zeros, p)

    # Initialize the result matrix with zeros
    result = [[0] * N for _ in range(N)]

    # Iterate over all possible B matrices
    for b_values in product(range(1, p), repeat=num_zeros):
        B = A.copy()
