import sys
from math import gcd
from functools import reduce

MOD = 998244353

def lcm(a, b):
    return a * b // gcd(a, b)

def factorize(n):
    factors = []
    for i in range(2, int(n**0.5) + 1):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 1:
        factors.append(n)
    return factors

def get_good_sequences(A):
    def dfs(path, last):
        if len(path) == len(A) + 1:
            if reduce(gcd, path) == 1:
                yield path
            return
        target = A[len(path) - 1]
        for p in range(1, target + 1):
            q = target // p
            if p * q == target and gcd(p, q) == 1:
                yield from dfs(path + [p * last], p)

    return list(dfs([1], 1))

def main():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    A = list(map(int, data[1:]))

    good_sequences = get_good_sequences(A)
    total_score = 0

    for seq in good_sequences:
        score = 1
        for num in seq:
            score = (score * num) % MOD
        total_score = (total_score + score) % MOD

    print(total_score)

