from typing import List
import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Build the adjacency list
        adj_list = [[] for _ in range(n)]
        for u, v, w in edges:
            adj_list[u].append((v, w))

        # Helper function to check if we can reach all nodes with max_weight
        def can_reach_all(max_weight):
            visited = [False] * n
            pq = [(0, 0)]  # (current_weight, current_node)

            while pq:
                current_weight, current_node = heapq.heappop(pq)
                if visited[current_node]:
                    continue
                visited[current_node] = True

                if current_node == 0:
                    continue

                for neighbor, weight in adj_list[current_node]:
                    if weight > max_weight or len(adj_list[neighbor]) >= threshold:
                        continue
                    heapq.heappush(pq, (weight, neighbor))

            return all(visited)

        # Binary search for the minimum possible maximum edge weight
        left, right = 1, 10**6
        result = -1

        while left <= right:
            mid = (left + right) // 2
            if can_reach_all(mid):
                result = mid
                right = mid - 1
            else:
                left = mid + 1

        return result
