        from collections import Counter

        # Count the frequency of each character
        freq = Counter(s)

        max_diff = 0

        # Iterate through each unique character
        for char in set(s):
            # Check if the frequency of the current character is odd or even
            if freq[char] % 2 == 0:
                # If even, try to find a character with an odd frequency
                for other_char in set(s):
                    if freq[other_char] % 2 != 0:
                        max_diff = max(max_diff, freq[other_char] - freq[char])
