class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        dp = [[0] * n for _ in range(n)]

        for i in range(n-1, -1, -1):
            dp[i][i] = 1
            for j in range(i+1, n):
                if s[i] == s[j]:
                    dp[i][j] = dp[i+1][j-1] + 2
                else:
                    dp[i][j] = max(dp[i+1][j], dp[i][j-1])

        target_length = dp[0][-1]
        if target_length > k + 1:
            return k + 1

        remaining_operations = k - (target_length - 1)
        left, right = 0, n - 1
        while left < right:
            if s[left] != s[right]:
                if dp[left+1][right] >= dp[left][right-1]:
                    left += 1
                else:
                    right -= 1
                remaining_operations -= 1
                if remaining_operations < 0:
                    break

        return target_length if remaining_operations >= 0 else target_length - 1
