    def maxSum(self, nums: List[int]) -> int:
        max_sum = float('-inf')
        current_sum = 0
        seen = set()

        for num in nums:
            if num not in seen:
                current_sum += num
                seen.add(num)
            else:
                max_sum = max(max_sum, current_sum)
                while nums[current_sum - 1] != num:
                    current_sum -= nums[current_sum - 1]
                    seen.remove(nums[current_sum - 1])
                current_sum += num
                seen.add(num)

        return max(max_sum, current_sum)
