class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        total_cells = n * n
        left, right = 0, total_cells + 1

        while left < right:
            mid = (left + right) // 2
            total_weight = mid * w

            if total_weight > maxWeight:
                right = mid
            else:
                left = mid + 1

        return left - 1
