class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        max_length = 0

        # Check all possible substrings from s and t
        for i in range(len(s)):
            for j in range(len(t)):
                for k in range(i + 1, len(s) + 1):
                    for l in range(j + 1, len(t) + 1):
                        combined = s[i:k] + t[j:l]
                        if combined == combined[::-1]:
                            max_length = max(max_length, len(combined))

        return max_length
