from typing import *
from collections import *

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        dp = [[[-1] * 2 for _ in range(n + 1)] for _ in range(k + 1)]

        def dfs(i, alt_sum, prod):
            if i == n:
                if alt_sum == k:
                    return prod
                else:
                    return float('-inf')

            if dp[alt_sum][i][prod % 2] != -1:
                return dp[alt_sum][i][prod % 2]

            # Option 1: Include the current number
            include = float('-inf')
            if alt_sum + nums[i] <= k and prod * nums[i] <= limit:
                include = dfs(i + 1, alt_sum + nums[i], prod * nums[i])

            # Option 2: Exclude the current number
            exclude = dfs(i + 1, alt_sum, prod)

            dp[alt_sum][i][prod % 2] = max(include, exclude)
            return dp[alt_sum][i][prod % 2]

        result = dfs(0, 0, 1)
        return result if result != float('-inf') else -1
