class Solution:
    def maxAdjacentDistance(self, nums: List[int]) -> int:
        n = len(nums)
        max_diff = 0

        # Check the differences between consecutive elements
        for i in range(n - 1):
            diff = abs(nums[i] - nums[i + 1])
            if diff > max_diff:
                max_diff = diff

        # Check the difference between the first and last element
        diff = abs(nums[0] - nums[n - 1])
        if diff > max_diff:
            max_diff = diff

        return max_diff
