from collections import *

class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(nums)
        graph = defaultdict(list)
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        max_length = 0
        min_nodes = float('inf')

        def dfs(node, parent):
            nonlocal max_length, min_nodes
            lengths = []
            for neighbor, weight in graph[node]:
                if neighbor != parent:
                    child_length, _ = dfs(neighbor, node)
                    if nums[node] != nums[neighbor]:
                        lengths.append(child_length + weight)

            if not lengths:
                return 0, 1

            lengths.sort()
            if len(lengths) > 1:
                max_length = max(max_length, lengths[-1] + lengths[-2])
                min_nodes = min(min_nodes, 2)
            elif lengths:
                max_length = max(max_length, lengths[-1])
                min_nodes = min(min_nodes, 1)

            if lengths:
                return lengths[-1], 1 + (len(lengths) > 1)
            else:
                return 0, 1

        dfs(0, -1)
        return [max_length, min_nodes]
```

