from typing import *
from collections import *

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        if k > self.count_permutations(n):
            return []

        result = []
        numbers = list(range(1, n + 1))
        k -= 1  # Convert to zero-indexed

        while n > 0:
            fact = self.factorial(n - 1)
            index, k = divmod(k, fact)
            result.append(numbers.pop(index))
            n -= 1

        return result

    def count_permutations(self, n: int) -> int:
        odd_count = (n + 1) // 2
        even_count = n // 2
        return self.factorial(odd_count) * self.factorial(even_count)

    def factorial(self, num: int) -> int:
        if num == 0 or num == 1:
            return 1
        result = 1
        for i in range(2, num + 1):
            result *= i
        return result
```

