    def totalNumbers(self, digits: List[int]) -> int:
        count = 0
        for i in range(10):
            if i % 2 == 0 and digits.count(i) > 0:
                for j in range(10):
                    if j != i and digits.count(j) > 0:
                        for k in range(10):
                            if k != i and k != j and digits.count(k) > 0:
                                count += 1
        return count
