from typing import *
from collections import *

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        result = [0] * n

        for i in range(n):
            remaining_words = words[:i] + words[i+1:]
            if len(remaining_words) < k:
                continue

            counter = Counter(''.join(remaining_words))
            target_word = max(counter, key=counter.get)
            target_count = counter[target_word]

            if target_count >= k:
                min_length = float('inf')
                for word in remaining_words:
                    if word.startswith(target_word):
                        min_length = min(min_length, len(word))
                result[i] = min_length

        return result
