class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        prefix_sum = [0] * (n + 1)
        cost_prefix_sum = [0] * (n + 1)

        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]
            cost_prefix_sum[i + 1] = cost_prefix_sum[i] + cost[i]

        dp = [[float('inf')] * (k + 1) for _ in range(n)]

        for i in range(n):
            dp[i][1] = (prefix_sum[i + 1] + k) * cost_prefix_sum[i + 1]

        for j in range(2, k + 1):
            for i in range(j - 1, n):
                dp[i][j] = min(dp[i][j], dp[m][j - 1] + (prefix_sum[i + 1] - prefix_sum[m + 1] + j * (prefix_sum[i + 1] - prefix_sum[m + 1])) * (cost_prefix_sum[i + 1] - cost_prefix_sum[m + 1]) for m in range(j - 2, i))

        return min(dp[i][k] for i in range(n))
